&lt;p&gt;&lt;span class=&quot;TextRun SCXW63653655 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW63653655 BCX0&quot;&gt;Apply today to join the team at Aviation Institute of Maintenance and help train the next generation of A&amp;amp;P mechanics.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW63653655 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
